const appServiceCases=[
{id:'telemetry',title:'Campus telemetry fan-out',copy:'One production flow feeds storage, dashboards and analytics without every sensor tracking the consumer list.',choices:['mqtt','coap','http'],reasonOptions:['one-to-many decoupling','broker mediation','resource request/response','web/API integration','observe/notify']},
{id:'maintenance',title:'Constrained resource read / observe',copy:'A local service reads /sensors/17/co2 and may subscribe to changes from a constrained node.',choices:['coap','mqtt','http'],reasonOptions:['resource-oriented exchange','observe/notify','constrained datagram model','broker mediation','web/API integration']},
{id:'webapi',title:'External web-facing API',copy:'A dashboard or external service integrates through familiar resource, status-code and representation semantics.',choices:['http','coap','mqtt'],reasonOptions:['web/API integration','resource-oriented exchange','topic fan-out','version-dependent transport','constrained datagram model']}
];
let selectedAppEvidence=null;
function renderAppProtocols(){renderProtocolPortraits();const board=document.getElementById('appEvidenceBoard');if(board){const placed=new Set(Object.keys(state.appEvidence||{}));board.innerHTML=`<div class="evidence-pool"><strong>Evidence fragments</strong>${appEvidenceItems.filter(x=>!placed.has(x.id)).map(x=>`<button type="button" class="evidence-fragment ${selectedAppEvidence===x.id?'selected':''}" data-app-evidence="${x.id}">${x.text}</button>`).join('')||'<span class="pool-empty">All fragments placed.</span>'}</div><div class="protocol-columns">${appProtocols.map(p=>`<div class="protocol-evidence-column" data-app-target="${p.id}"><h4>${p.name}</h4><small>${p.summary}</small><div>${appEvidenceItems.filter(x=>state.appEvidence?.[x.id]===p.id).map(x=>`<button type="button" class="placed-evidence ${state.appEvidenceAudited?(x.target===p.id?'good':'bad'):''}" data-unplace-app="${x.id}">${x.text}</button>`).join('')||'<em>Drop / tap evidence here</em>'}</div></div>`).join('')}</div>`;board.querySelectorAll('[data-app-evidence]').forEach(b=>b.onclick=()=>{selectedAppEvidence=selectedAppEvidence===b.dataset.appEvidence?null:b.dataset.appEvidence;renderAppProtocols()});board.querySelectorAll('[data-app-target]').forEach(z=>{z.onclick=e=>{if(e.target.closest('[data-unplace-app]'))return;if(!selectedAppEvidence)return;state.appEvidence=state.appEvidence||{};state.appEvidence[selectedAppEvidence]=z.dataset.appTarget;selectedAppEvidence=null;state.appEvidenceAudited=false;save();renderAppProtocols();updateGates()}});board.querySelectorAll('[data-unplace-app]').forEach(b=>b.onclick=()=>{delete state.appEvidence[b.dataset.unplaceApp];state.appEvidenceAudited=false;save();renderAppProtocols();updateGates()})}
 const sg=document.getElementById('appServiceGrid');if(sg){sg.innerHTML=appServiceCases.map(c=>{const choice=state.appServiceChoices?.[c.id]||'',reasons=new Set(state.appServiceReasons?.[c.id]||[]);return `<article class="service-fit-card"><span class="case-kicker">Service decision</span><h3>${c.title}</h3><p>${c.copy}</p><div class="protocol-choice-row">${c.choices.map(id=>`<button type="button" class="protocol-choice ${choice===id?'active':''}" data-service-choice="${c.id}" data-protocol="${id}">${appProtocols.find(p=>p.id===id).name}</button>`).join('')}</div><div class="reason-row"><b>Evidence that drove us</b>${c.reasonOptions.map(r=>`<button type="button" class="reason-chip ${reasons.has(r)?'active':''}" data-service-reason="${c.id}" data-reason="${r}">${r}</button>`).join('')}</div></article>`}).join('');sg.querySelectorAll('[data-service-choice]').forEach(b=>b.onclick=()=>{state.appServiceChoices=state.appServiceChoices||{};state.appServiceChoices[b.dataset.serviceChoice]=b.dataset.protocol;save();renderAppProtocols();updateGates()});sg.querySelectorAll('[data-service-reason]').forEach(b=>b.onclick=()=>{state.appServiceReasons=state.appServiceReasons||{};const arr=new Set(state.appServiceReasons[b.dataset.serviceReason]||[]);arr.has(b.dataset.reason)?arr.delete(b.dataset.reason):arr.add(b.dataset.reason);state.appServiceReasons[b.dataset.serviceReason]=[...arr].slice(-1);save();renderAppProtocols();updateGates()})}
 const fb=document.getElementById('appEvidenceFeedback');if(fb){const total=appEvidenceItems.length,placed=Object.keys(state.appEvidence||{}).length,correct=appEvidenceItems.filter(x=>state.appEvidence?.[x.id]===x.target).length;fb.className='audit-feedback '+(state.appEvidenceAudited?(correct===total?'good':'warn'):'');fb.textContent=state.appEvidenceAudited?(correct===total?'Evidence map coherent. Now use it rather than protocol familiarity.':`${correct}/${total} fragments are coherent. Re-open the boundaries that do not fit.`):`${placed}/${total} fragments placed. Audit only after committing the whole map.`}}
 const fit=document.getElementById('serviceFitLab');if(fit)fit.hidden=false
const appAudit=document.getElementById('checkAppEvidence');if(appAudit)appAudit.onclick=()=>{if(Object.keys(state.appEvidence||{}).length<appEvidenceItems.length)return toast('Place every evidence fragment first');state.appEvidenceAudited=true;save();renderAppProtocols();updateGates()};

