 const zones=document.getElementById('interopZones');if(zones){zones.innerHTML=interopZones.map(([id,name])=>`<div class="contract-zone" data-interop-zone="${id}"><strong>${name}</strong><div>${interopArtifacts.filter(x=>state.interopMap?.[x.id]===id).map(x=>`<button type="button" class="placed-contract-piece" data-unplace-interop="${x.id}"><b>${x.name}</b><span>${x.example}</span></button>`).join('')||'<em>Place relevant pieces here</em>'}</div></div>`).join('');zones.querySelectorAll('[data-interop-zone]').forEach(z=>z.onclick=e=>{if(e.target.closest('[data-unplace-interop]'))return;if(!selectedInteropArtifact)return;state.interopMap=state.interopMap||{};state.interopMap[selectedInteropArtifact]=z.dataset.interopZone;selectedInteropArtifact=null;save();renderInterop();updateGates()});zones.querySelectorAll('[data-unplace-interop]').forEach(b=>b.onclick=()=>{delete state.interopMap[b.dataset.unplaceInterop];save();renderInterop();updateGates()})}
