function placeProto(pid,layer,c){const tile=protocolTiles.find(x=>x.id===pid);if(!tile)return;if(tile.layer!==layer)return toast(`${tile.name} solves ${tile.layer}, not ${layer}`);state.compositions[c]=state.compositions[c]||{};state.compositions[c][layer]=pid;selectedProto=null;state.composeValid[c]=false;save();renderComposer();updateGates()}
function renderComposer(){const concept=document.getElementById('compositionConceptTest');state.compositionConcept=state.compositionConcept||{alternatives:null,coexist:null};if(concept){const x=state.compositionConcept;concept.innerHTML=`<div class="composition-test-head"><span class="eyebrow">Abstraction audit</span><h3>Before composing: repair the sentence “MQTT versus Thread”.</h3></div><div class="composition-test-grid"><section><strong>Are MQTT and Thread direct alternatives at one responsibility?</strong><div><button type="button" class="concept-choice ${x.alternatives==='no'?'active':''}" data-comp-concept="alternatives" data-comp-value="no">No · they solve different responsibility ranges</button><button type="button" class="concept-choice ${x.alternatives==='yes'?'active':''}" data-comp-concept="alternatives" data-comp-value="yes">Yes · choose one or the other</button></div></section><section><strong>Could they coexist in one system?</strong><div><button type="button" class="concept-choice ${x.coexist==='yes'?'active':''}" data-comp-concept="coexist" data-comp-value="yes">Yes · if the remaining transport/application dependencies are compatible</button><button type="button" class="concept-choice ${x.coexist==='no'?'active':''}" data-comp-concept="coexist" data-comp-value="no">No · one necessarily replaces the other</button></div></section></div>${x.alternatives&&x.coexist?`<p class="composition-concept-feedback">${x.alternatives==='no'&&x.coexist==='yes'?'The abstraction model is coherent: compare within a responsibility, compose across compatible responsibilities.':'Keep this claim visible and use the two stacks below to test it rather than guessing from names.'}</p>`:''}`;concept.querySelectorAll('[data-comp-concept]').forEach(b=>b.onclick=()=>{state.compositionConcept[b.dataset.compConcept]=b.dataset.compValue;save();renderComposer();updateGates()})}const c=state.composeCase;state.compositions[c]=state.compositions[c]||{};const fixed=c==='a'?{link:'154',adaptation:'6lowpan',network:'ipv6'}:{link:'wifi',adaptation:'none',network:'ipv6'};Object.entries(fixed).forEach(([k,v])=>{state.compositions[c][k]=v});const d=state.compositions[c];document.querySelectorAll('.composer-tab').forEach(b=>b.classList.toggle('active',b.dataset.composeCase===c));document.getElementById('caseBrief').innerHTML=`<b>${cases[c].title}</b><br>${cases[c].copy}`;const used=new Set(Object.values(d));document.getElementById('protocolPalette').innerHTML=protocolTiles.filter(t=>!used.has(t.id)).map(t=>`<div class="protocol-tile ${selectedProto===t.id?'selected':''}" draggable="true" data-proto="${t.id}">${t.name}<small>${t.note}</small></div>`).join('');document.getElementById('protocolStack').innerHTML=layers.map(([id,name])=>{const pid=d[id],t=protocolTiles.find(x=>x.id===pid);return `<div class="protocol-slot" data-proto-layer="${id}"><strong>${name}</strong><div class="protocol-drop">${t?`<div class="protocol-tile" data-remove-proto="${id}">${t.name}<small>${t.note}</small></div>`:'Drop protocol here'}</div></div>`}).join('');document.querySelectorAll('[data-proto]').forEach(x=>{x.ondragstart=e=>e.dataTransfer.setData('text/plain',x.dataset.proto);x.onclick=()=>{selectedProto=selectedProto===x.dataset.proto?null:x.dataset.proto;renderComposer()}});document.querySelectorAll('[data-proto-layer]').forEach(s=>{s.ondragover=e=>{e.preventDefault();s.classList.add('dragover')};s.ondragleave=()=>s.classList.remove('dragover');s.ondrop=e=>{e.preventDefault();s.classList.remove('dragover');placeProto(e.dataTransfer.getData('text/plain'),s.dataset.protoLayer,c)};s.onclick=e=>{if(e.target.closest('[data-remove-proto]'))return;if(selectedProto)placeProto(selectedProto,s.dataset.protoLayer,c)}});document.querySelectorAll('[data-remove-proto]').forEach(x=>x.onclick=()=>{delete state.compositions[c][x.dataset.removeProto];state.composeValid[c]=false;save();renderComposer();updateGates()});const fb=document.getElementById('composerFeedback');fb.className='composer-feedback '+(state.composeValid[c]?'good':'');fb.textContent=state.composeValid[c]?'Composition checked: technically coherent for the stated scenario.':'Build the stack, then check it.';const campus=document.getElementById('campusDecision');if(campus)campus.hidden=!(state.composeValid.a&&state.composeValid.b)}
document.querySelectorAll('[data-compose-case]').forEach(b=>b.onclick=()=>{state.composeCase=b.dataset.composeCase;save();renderComposer()});document.getElementById('checkStack').onclick=()=>{const c=state.composeCase,got=state.compositions[c]||{},exp=cases[c].expected;const complete=layers.every(([id])=>got[id]);if(!complete)return toast('Complete all five responsibilities first');const ok=Object.keys(exp).every(k=>got[k]===exp[k]);state.composeValid[c]=ok;save();renderComposer();updateGates();if(!ok)toast('Valid pieces can still form the wrong composition — inspect the assumptions')};
const campusChoices=['Brokered pub/sub for telemetry + direct resource exchange where needed','One application protocol for every flow','Hybrid / different patterns for different flows','Not enough information yet'];
