const deliveryCases=[
{id:'ambient',k:'A',title:'Ambient telemetry',copy:'The dashboard computes a rolling trend from one sample per minute.'},
{id:'alarm',k:'B',title:'High-CO₂ alert',copy:'A threshold event must cause the monitoring service to react, even if the first delivery path is disrupted.'},
{id:'command',k:'C',title:'Ventilation operation',copy:'A retry after timeout must not make the physical operation happen twice.'},
{id:'offline',k:'D',title:'Temporarily offline consumer',copy:'A consumer disappears for several minutes and later reconnects.'}
];
const contractDimensions=[['loss','Can one occurrence be lost?',['Tolerable','Not tolerable']],['duplicate','Can one delivery / effect happen twice?',['Tolerable','Not tolerable']],['offline','Must the service bridge a temporary disconnect?',['Yes','No / not required']]];
const deliveryZones=[['transport','Transport'],['appProtocol','Application protocol'],['application','Application / system semantics'],['intermediary','Intermediary / session state'],['physical','Physical / control loop']];
const deliveryMechanisms=[
{id:'tcp',name:'TCP retransmission + in-order byte stream',note:'loss recovery + ordering',zone:'transport'},
{id:'mqtt',name:'MQTT QoS acknowledgement flows',note:'message-delivery semantics',zone:'appProtocol'},
{id:'coap',name:'CoAP CON / ACK + retransmission',note:'confirmation + retry',zone:'appProtocol'},
{id:'buffer',name:'Broker/session buffering or store-and-forward',note:'retain / replay across absence',zone:'intermediary'},
{id:'idem',name:'Stable operation ID + deduplication / idempotency',note:'prevent duplicate side effect',zone:'application'},
{id:'feedback',name:'Measured physical-state feedback',note:'observe the resulting state',zone:'physical'}
];
const crashOutcomes=['The physical operation can execute twice','TCP guarantees the application will not retry','MQTT QoS 1 guarantees one physical effect','The second command is automatically ignored'];
const crashMitigationOptions=[['opid','stable operation ID'],['dedup','durable deduplication / idempotency'],['feedback','physical-state feedback'],['tcp','more TCP retransmission'],['qos','higher MQTT QoS only'],['fresh','freshness / sequence check']];
function placeDeliveryMechanism(id,zone){if(!deliveryMechanisms.find(m=>m.id===id))return;state.deliveryMechanisms=state.deliveryMechanisms||{};state.deliveryMechanisms[id]=zone;selectedDeliveryMechanism=null;save();renderDeliverySemantics();updateGates()}
function renderDeliverySemantics(){const gh=document.getElementById('guaranteeCaseGrid');if(gh){gh.innerHTML=deliveryCases.map(c=>{const d=state.deliveryContracts?.[c.id]||{};return `<article class="guarantee-case contract-case"><span class="case-kicker">Case ${c.k}</span><h3>${c.title}</h3><p>${c.copy}</p>${contractDimensions.map(([id,label,opts])=>`<div class="contract-dimension"><b>${label}</b><div>${opts.map(o=>`<button type="button" class="guarantee-option ${d[id]===o?'active':''}" data-contract-case="${c.id}" data-dimension="${id}" data-value="${o}">${o}</button>`).join('')}</div></div>`).join('')}</article>`}).join('');gh.querySelectorAll('[data-contract-case]').forEach(b=>b.onclick=()=>{state.deliveryContracts=state.deliveryContracts||{};state.deliveryContracts[b.dataset.contractCase]=state.deliveryContracts[b.dataset.contractCase]||{};state.deliveryContracts[b.dataset.contractCase][b.dataset.dimension]=b.dataset.value;save();renderDeliverySemantics();updateGates()})}
 const placed=new Set(Object.keys(state.deliveryMechanisms||{}));const ph=document.getElementById('mechanismPalette');if(ph){ph.innerHTML=deliveryMechanisms.filter(m=>!placed.has(m.id)).map(m=>`<div class="mechanism-chip ${selectedDeliveryMechanism===m.id?'selected':''}" draggable="true" data-delivery-mech="${m.id}">${m.name}<span>${m.note}</span></div>`).join('');ph.querySelectorAll('[data-delivery-mech]').forEach(x=>{x.ondragstart=e=>e.dataTransfer.setData('text/plain',x.dataset.deliveryMech);x.onclick=()=>{selectedDeliveryMechanism=selectedDeliveryMechanism===x.dataset.deliveryMech?null:x.dataset.deliveryMech;renderDeliverySemantics()}})}
 const zh=document.getElementById('guaranteeZones');if(zh){zh.innerHTML=deliveryZones.map(([id,name])=>`<div class="guarantee-zone" data-delivery-zone="${id}"><strong>${name}</strong><div class="guarantee-zone-items">${deliveryMechanisms.filter(m=>state.deliveryMechanisms?.[m.id]===id).map(m=>`<span class="placed-mechanism" data-unplace-delivery="${m.id}">${m.name}</span>`).join('')}</div></div>`).join('');zh.querySelectorAll('[data-delivery-zone]').forEach(z=>{z.ondragover=e=>{e.preventDefault();z.classList.add('dragover')};z.ondragleave=()=>z.classList.remove('dragover');z.ondrop=e=>{e.preventDefault();z.classList.remove('dragover');placeDeliveryMechanism(e.dataTransfer.getData('text/plain'),z.dataset.deliveryZone)};z.onclick=e=>{if(e.target.closest('[data-unplace-delivery]'))return;if(selectedDeliveryMechanism)placeDeliveryMechanism(selectedDeliveryMechanism,z.dataset.deliveryZone)}});zh.querySelectorAll('[data-unplace-delivery]').forEach(x=>x.onclick=()=>{delete state.deliveryMechanisms[x.dataset.unplaceDelivery];save();renderDeliverySemantics();updateGates()})}
 const cw=document.getElementById('crashWindow');if(cw){const m=new Set(state.crashMitigation||[]);cw.innerHTML=`<div class="crash-question"><b>What can happen?</b><div class="crash-options">${crashOutcomes.map(o=>`<button type="button" class="crash-option ${state.crashOutcome===o?'active':''}" data-crash-outcome="${o}">${o}</button>`).join('')}</div>${state.crashOutcome?`<small>${state.crashOutcome===crashOutcomes[0]?'Correct scope: a lost acknowledgement can reopen the application operation even if lower layers behaved correctly.':'Reconsider the boundary between message delivery and application/physical effect.'}</small>`:''}</div><div class="crash-question"><b>What would you add to close the window?</b><div class="crash-options">${crashMitigationOptions.map(([id,label])=>`<button type="button" class="crash-option ${m.has(id)?'active':''}" data-crash-mitigation="${id}">${label}</button>`).join('')}</div></div>`;cw.querySelectorAll('[data-crash-outcome]').forEach(b=>b.onclick=()=>{state.crashOutcome=b.dataset.crashOutcome;save();renderDeliverySemantics();updateGates()});cw.querySelectorAll('[data-crash-mitigation]').forEach(b=>b.onclick=()=>{const x=new Set(state.crashMitigation||[]);x.has(b.dataset.crashMitigation)?x.delete(b.dataset.crashMitigation):x.add(b.dataset.crashMitigation);state.crashMitigation=[...x];save();renderDeliverySemantics();updateGates()})}const contractsDone=deliveryCases.every(c=>contractDimensions.every(([id])=>state.deliveryContracts?.[c.id]?.[id]));const mechanismLab=document.getElementById('mechanismLab');if(mechanismLab)mechanismLab.hidden=false;const mechanismsDone=deliveryMechanisms.every(m=>state.deliveryMechanisms?.[m.id]);const crashSection=document.getElementById('crashWindowSection');if(crashSection)crashSection.hidden=false}
function deliverySnapshot(){const contracts=deliveryCases.filter(c=>Object.values(state.deliveryContracts?.[c.id]||{}).some(Boolean)).length;const mechanisms=deliveryMechanisms.filter(m=>state.deliveryMechanisms?.[m.id]).length;const mitigation=(state.crashMitigation||[]).map(id=>crashMitigationOptions.find(x=>x[0]===id)?.[1]||id).join(' / ')||'—';return `<div><b>Core crash-window result</b><span>${state.crashOutcome||'—'}</span></div><div><b>Mitigation set</b><span>${mitigation}</span></div><div><b>Reference boards explored</b><span>${contracts}/4 service contracts · ${mechanisms}/6 mechanism scopes</span></div>`}

const incidents=[['loss','Packet loss','Sam reports that one telemetry datagram disappears on a degraded path.'],['duplicate','Duplicate action','Sam reports that one ventilation command is processed twice after a retry.'],['broker','Broker unavailable','Leila reports that devices can reach the network, but the MQTT broker is unavailable.'],['sleep','Sleeping sensor','Sam reports that a sleepy node is offline when a direct request arrives.']];
const failureTraceOptions={guarantee:['fresh-enough telemetry','event eventually reaches the service','no duplicate application / physical operation','service survives a temporary disconnect','physical state is confirmed'],scope:['transport delivery','application-protocol delivery','application / operation semantics','intermediary / session state','physical control loop'],revision:['retry / acknowledgement mechanism','persistent buffer / store-and-forward','stable operation ID + deduplication','freshness / sequence check','broker/service availability monitoring','measured state feedback','change the interaction pattern'],evidence:['transport / protocol acknowledgement','broker/session replay observed','deduplication log / operation record','freshness / sequence accepted','service availability signal','measured physical state']};
function renderIncidents(){document.getElementById('incidentGrid').innerHTML=incidents.map(i=>`<button class="incident ${state.incident===i[0]?'active':''}" data-incident="${i[0]}" type="button"><b>${i[1]}</b><span>${i[2]}</span></button>`).join('');document.querySelectorAll('[data-incident]').forEach(b=>b.onclick=()=>{state.incident=b.dataset.incident;state.failureTrace={guarantee:'',scope:'',revision:'',evidence:''};save();renderIncidents();updateGates()});const host=document.getElementById('failureTraceBoard');if(host){const steps=[['guarantee','1 · Required guarantee'],['scope','2 · Where the current scope is insufficient'],['revision','3 · Revision'],['evidence','4 · Evidence after the fix']];host.innerHTML=`<div class="failure-chain">${steps.map(([id,label],i)=>`<section class="failure-step"><span>${label}</span><div>${failureTraceOptions[id].map(o=>`<button type="button" class="failure-option ${state.failureTrace?.[id]===o?'active':''}" data-failure-step="${id}" data-failure-value="${o}">${o}</button>`).join('')}</div></section>${i<steps.length-1?'<b class="failure-arrow">→</b>':''}`).join('')}</div><p class="failure-note">The board does not certify your chain. It makes the causal claim explicit so another group can attack it at the STOP.</p>`;host.querySelectorAll('[data-failure-step]').forEach(b=>b.onclick=()=>{state.failureTrace=state.failureTrace||{};state.failureTrace[b.dataset.failureStep]=b.dataset.failureValue;save();renderIncidents();updateGates()})}}

function updateGates(){
 const convDone=convoCases.every(c=>state.conversations[c.id]?.pattern&&state.conversationConsequences?.[c.id]);document.getElementById('a1Next').disabled=!convDone;
 document.getElementById('a2Next').disabled=state.actors.filter(Boolean).length<2||state.messages.length<2;
 const roleDone=responsibilities.every(r=>Object.values(state.stackRoles).some(a=>(a||[]).includes(r.id)));document.getElementById('a3Next').disabled=!roleDone;
 const netDone=networkCards.every(c=>state.networkDetective[c.id]?.role&&state.networkDetective[c.id]?.boundary);document.getElementById('a4Next').disabled=!netDone;
 const portraitsDone=appPortraitDefs.every(p=>state.appPortraits?.[p.id]);const serviceDone=appServiceCases.every(c=>state.appServiceChoices?.[c.id]&&(state.appServiceReasons?.[c.id]||[]).length>=1);document.getElementById('a5Next').disabled=!(portraitsDone&&serviceDone);
 document.getElementById('a6Next').disabled=(state.semanticRepair||[]).length<2;
 const conceptDone=state.compositionConcept?.alternatives&&state.compositionConcept?.coexist;document.getElementById('a7Next').disabled=!(state.composeValid.a&&state.composeValid.b&&conceptDone);
 document.getElementById('a8Next').disabled=!(state.crashOutcome&&(state.crashMitigation||[]).length>=2);
 const trace=state.failureTrace||{};document.getElementById('a9Next').disabled=!(state.incident&&trace.guarantee&&trace.scope&&trace.revision&&trace.evidence);updateStopNextButtons()
}

function renderSnapshots(){const s1=document.getElementById('stop1Snapshot');if(s1)s1.innerHTML=convoCases.map(c=>{const d=state.conversations[c.id]||{},p=conversationPatterns.find(x=>x[0]===d.pattern),cv=state.conversationConsequences?.[c.id],cl=c.testOptions.find(x=>x[0]===cv)?.[1];return `<div><b>${c.title}</b><span>${p?.[1]||'—'} · ${c.profile[0]} · ${c.profile[1]} · ${c.profile[2]}${cl?` · consequence: ${cl}`:''}</span></div>`}).join('');const s2=document.getElementById('stop2Snapshot');if(s2)s2.innerHTML=`<b>${state.choreoScenario||'telemetry'} choreography</b>${state.messages.map(m=>`<div>${m.from} → ${m.to} · ${m.label}</div>`).join('')}`;const s3=document.getElementById('stop3Snapshot');if(s3)s3.innerHTML=layers.map(([id,n])=>`<div><b>${n}</b><span>${(state.stackRoles[id]||[]).map(rid=>responsibilities.find(r=>r.id===rid)?.text).join(' · ')||'—'}</span></div>`).join('');const s6=document.getElementById('stop6Snapshot');if(s6)s6.innerHTML=interopZones.map(([id,n])=>`<div><b>${n}</b><span>${interopArtifacts.filter(x=>state.interopMap?.[x.id]===id).map(x=>x.name).join(' · ')||'—'}</span></div>`).join('')+`<div><b>Supplier-B repair</b><span>${(state.semanticRepair||[]).map(id=>semanticRepairOptions.find(x=>x[0]===id)?.[1]).filter(Boolean).join(' · ')||'—'}</span></div>`;const s7=document.getElementById('stop7Snapshot');if(s7)s7.innerHTML=`<div><b>Case A</b><span>${stackText('a')}</span></div><div><b>Case B</b><span>${stackText('b')}</span></div><div><b>Campus position</b><span>${state.campusChoice||'—'}</span></div><div><b>Evidence / caveat</b><span>${(state.campusEvidence||[]).join(' · ')||'—'} · caveat: ${state.campusCaveat||'—'}</span></div>`;const s8=document.getElementById('stop8Snapshot');if(s8)s8.innerHTML=deliverySnapshot();const s9=document.getElementById('stop9Snapshot');if(s9)s9.innerHTML=`<div><b>Incident</b><span>${incidents.find(x=>x[0]===state.incident)?.[1]||'—'}</span></div><div><b>Required guarantee</b><span>${state.failureTrace?.guarantee||'—'}</span></div><div><b>Insufficient scope</b><span>${state.failureTrace?.scope||'—'}</span></div><div><b>Revision</b><span>${state.failureTrace?.revision||'—'}</span></div><div><b>Evidence after fix</b><span>${state.failureTrace?.evidence||'—'}</span></div>`}
function stackText(c){const d=state.compositions[c]||{};return layers.slice().reverse().map(([id])=>protocolTiles.find(t=>t.id===d[id])?.name||'—').join(' → ')}
function renderDrawer(){const body=document.getElementById('drawerBody');if(!body)return;const d=loadMissionDossier(),s1=d.session1||{};body.innerHTML=`<section class="drawer-section"><b>Session 1 handover</b><p>${s1.architectureClass?.label||'Generic handover'}${s1.priorityRequirements?.length?' · priorities: '+s1.priorityRequirements.map(x=>x.label).join(' / '):''}</p></section><section class="drawer-section"><b>Conversation contracts</b><p>${Object.keys(state.conversations).length}/4 situations described.</p></section><section class="drawer-section"><b>Message choreography</b><p>${state.messages.length} messages · ${state.actors.filter(Boolean).length} actors.</p></section><section class="drawer-section"><b>Application evidence map</b><p>${Object.keys(state.appEvidence||{}).length}/${appEvidenceItems.length} evidence fragments placed · ${Object.keys(state.appServiceChoices||{}).length}/3 service decisions.</p></section><section class="drawer-section"><b>Interoperability contract</b><p>${Object.keys(state.interopMap||{}).length}/${interopArtifacts.length} pieces scoped · ${(state.semanticRepair||[]).length} supplier-B repair actions.</p></section><section class="drawer-section"><b>Stack A</b><p>${stackText('a')}</p></section><section class="drawer-section"><b>Stack B</b><p>${stackText('b')}</p></section><section class="drawer-section"><b>Campus position</b><p>${state.campusChoice||'Not committed yet'}${state.campusCaveat?' · caveat: '+state.campusCaveat:''}</p></section><section class="drawer-section"><b>Delivery semantics</b><p>${Object.keys(state.deliveryContracts||{}).length}/4 delivery contracts · ${Object.keys(state.deliveryMechanisms||{}).length}/6 mechanisms scoped.</p></section>`}
const drawer=document.getElementById('stackDrawer'),scrim=document.getElementById('drawerScrim');document.getElementById('stackBtn').onclick=()=>{closeFieldGuide();drawer.classList.add('open');drawer.setAttribute('aria-hidden','false');scrim.hidden=false};function closeDrawer(){drawer.classList.remove('open');drawer.setAttribute('aria-hidden','true');scrim.hidden=true}document.getElementById('drawerClose').onclick=closeDrawer;scrim.onclick=closeDrawer;
const fieldGuideDrawer=document.getElementById('fieldGuideDrawer'),fieldGuideScrim=document.getElementById('fieldGuideScrim');function closeFieldGuide(){fieldGuideDrawer?.classList.remove('open');fieldGuideDrawer?.setAttribute('aria-hidden','true');if(fieldGuideScrim)fieldGuideScrim.hidden=true}document.getElementById('fieldGuideBtn').onclick=()=>{closeDrawer();fieldGuideDrawer.classList.add('open');fieldGuideDrawer.setAttribute('aria-hidden','false');fieldGuideScrim.hidden=false};document.getElementById('closeFieldGuide').onclick=closeFieldGuide;fieldGuideScrim.onclick=closeFieldGuide;


const recallPrompts=[
 {id:'thread',q:'Why is Thread not the same kind of object as TCP?',a:'Thread is an IPv6-based IoT networking suite spanning several networking responsibilities; TCP is a transport protocol that provides a reliable in-order byte stream.'},
 {id:'coexist',q:'Why can MQTT and Wi-Fi coexist without competing?',a:'They solve different responsibilities: MQTT defines application-level publish/subscribe messaging, while Wi-Fi provides local network access/link functions.'},
 {id:'meaning',q:'Why is a delivered JSON payload not automatically semantically interoperable?',a:'Delivery proves the bytes arrived, not that the receiver shares the phenomenon, unit, source, timestamp, identifiers or data model needed to interpret them.'},
 {id:'qos',q:'What is the difference between TCP reliable delivery and MQTT message QoS?',a:'TCP guarantees a reliable in-order byte stream between transport endpoints. MQTT QoS defines delivery semantics for MQTT messages above that transport, with its own acknowledgement flows and scope.'},
 {id:'duplicate',q:'Why can at-least-once message delivery create a duplicate application effect?',a:'At-least-once permits duplicate message delivery. Without idempotence, deduplication or operation IDs, a repeated message can trigger the same application or physical action twice.'},
 {id:'physical',q:'What evidence would confirm that a physical command actually took effect?',a:'Measured physical-state feedback or another observation of the resulting state. A transport/application acknowledgement alone does not prove the actuator or physical process succeeded.'}
];
function renderMemoryLock(){const host=document.getElementById('memoryLock');if(!host)return;const done=recallPrompts.filter(x=>state.recall?.[x.id]).length;host.innerHTML=`<div class="memory-head"><span class="memory-icon">↺</span><div><strong>30-second memory lock</strong><small>Say the answer before revealing it.</small></div></div><div class="memory-grid">${recallPrompts.map((x,i)=>{const shown=!!state.recall?.[x.id];return `<article class="memory-card ${shown?'revealed':''}"><span class="memory-number">${i+1}</span><strong>${x.q}</strong>${shown?`<p>${x.a}</p>`:`<button type="button" class="recall-reveal" data-recall="${x.id}">Reveal after answering</button>`}</article>`}).join('')}</div><div class="memory-progress">${done} / ${recallPrompts.length} revealed</div>`;host.querySelectorAll('[data-recall]').forEach(b=>b.onclick=()=>{state.recall={...(state.recall||{}),[b.dataset.recall]:true};save();renderMemoryLock()});const synth=document.getElementById('sessionSynthesis');if(synth)synth.hidden=done<recallPrompts.length}

function exportSession(){const dossier=publishMissionDossier(),blob=new Blob([JSON.stringify({course:'IoT Systems Design',artifact:'Campus IoT mission dossier',exportedAt:new Date().toISOString(),missionDossier:dossier,sessionProgress:{session2:state}},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='iot-campus-mission-dossier.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),800)}document.getElementById('exportBtn').onclick=exportSession;const finishExport=document.getElementById('finishExport');if(finishExport)finishExport.onclick=exportSession;document.getElementById('importInput').onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const parsed=JSON.parse(r.result);if(parsed.missionDossier)localStorage.setItem(MISSION_KEY,JSON.stringify(parsed.missionDossier));const candidate=parsed.sessionProgress?.session2||parsed.data;if(candidate){state={...defaultState(),...candidate};state.maxUnlockedScreen=Math.max(Number(state.maxUnlockedScreen)||0,Number(state.screen)||0,ACTIVITY_ENTRY[Math.min(Number(state.frontier)||0,8)]||0);save();renderAll();show(Math.min(Number(state.screen)||0,screens.length-1),false);toast('Mission dossier + Session 2 progress imported')}else if(parsed.missionDossier){renderMissionHandover();renderDrawer();toast('Session 1 Mission dossier loaded')}else{throw new Error()}}catch{toast('Invalid file')}};r.readAsText(f)};document.getElementById('resetBtn').onclick=()=>{if(confirm('Reset all Session 2 work on this browser?')){state=defaultState();try{const d=loadMissionDossier();d.session2={};localStorage.setItem(MISSION_KEY,JSON.stringify(d))}catch{}save();renderAll();show(0,false)}};
